[tasks.probe]
description = "Run the one-shot nondefault SDK image consumer and terminal cleanup"
shell = "node --input-type=module-typescript -e"
run = '''
import {readFileSync,writeFileSync,existsSync,realpathSync} from 'node:fs';
import {join} from 'node:path';import {homedir} from 'node:os';import {pathToFileURL} from 'node:url';
import {execFileSync} from 'node:child_process';import {createHash,randomUUID} from 'node:crypto';
import {strict as assert} from 'node:assert';
const root=realpathSync(join(homedir(),'temp/agent/depot-sdk-custom-runtime-20261018'));
assert.equal(execFileSync('git',['rev-parse','--show-toplevel'],{cwd:root,encoding:'utf8'}).trim(),root);
assert.equal(execFileSync('git',['status','--porcelain'],{cwd:root,encoding:'utf8'}).trim(),'');
const source=execFileSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8'}).trim();
const fixture=join(root,'.depot/probe/platform-sdk');const manifest=JSON.parse(readFileSync(join(fixture,'manifest.json'),'utf8'));
const state=join(homedir(),'temp/agent/depot-platform-buildkit-evidence-20261018');
const path=join(state,'sdk-custom-runtime-consumer.json');assert(!existsSync(path));
const admitted=JSON.parse(readFileSync(join(state,'sdk-custom-runtime-input.json'),'utf8'));assert(admitted.inputVerified);
assert.equal(admitted.expectedManifestDigest,manifest.imageManifestDigest);assert.equal(admitted.image.config.diskSizeBytes,manifest.imageDiskSizeBytes);
const sdkRoot=join(homedir(),'temp/agent/depot-developer-capabilities-20261018/node_modules/@depot/sandbox');
assert.equal(JSON.parse(readFileSync(join(sdkRoot,'package.json'),'utf8')).version,manifest.sdkVersion);
const {createClient,Sandbox}=await import(pathToFileURL(join(sdkRoot,'dist/index.js')).href);
const token=execFileSync('depot',['login','token'],{encoding:'utf8',maxBuffer:64*1024}).trim();assert(token&&!/\s/.test(token));
const nonce=randomUUID();const request={...manifest.request,name:'research-sdk-custom-'+nonce,runtime:{imageRef:manifest.imageReference}};
const result={schemaVersion:1,source,repositoryBase:manifest.repositoryBase,startedAt:new Date().toISOString(),sdkVersion:manifest.sdkVersion,request,forecast:manifest.forecast,createCallCount:0,checks:[],cleanup:{},registryControls:[],credentialsRetained:false};
let registryAuthorization;function retain(){const value=JSON.stringify(result,null,2)+'\n';for(const secret of [token,Buffer.from('x-token:'+token).toString('base64'),registryAuthorization?.slice(7)].filter(Boolean))assert(!value.includes(secret));writeFileSync(path,value);}
function view(value){return {sandboxId:value.sandboxId,status:value.status,name:value.name,resources:value.resources,runtime:value.runtime,architecture:value.architecture,createdAt:value.createdAt,startedAt:value.startedAt,expiresAt:value.expiresAt,stoppedAt:value.stoppedAt,errorMessage:value.errorMessage};}
function errorView(error){return {name:error?.name,message:String(error?.message??error).replaceAll(token,'[redacted]'),code:error?.code};}
async function checkTag(phase){const url='https://l4zncjjbj5.registry.depot.dev/v2/research-reuse-20261018/manifests/tools-r2-git256';let response=await fetch(url,{headers:{...(registryAuthorization?{Authorization:registryAuthorization}:{}),Accept:'application/vnd.oci.image.manifest.v1+json'},redirect:'error',signal:AbortSignal.timeout(15000)});if(response.status===401&&!registryAuthorization){const challenge=response.headers.get('www-authenticate');assert(challenge?.startsWith('Bearer '));const fields=Object.fromEntries([...challenge.matchAll(/([a-zA-Z]+)="([^"]*)"/gu)].map(match=>[match[1],match[2]]));const realm=new URL(fields.realm);assert.equal(realm.origin,'https://api.depot.dev');assert.equal(realm.pathname,'/auth/registry/token');realm.searchParams.set('service',fields.service);realm.searchParams.set('scope','repository:research-reuse-20261018:pull');const auth=await fetch(realm,{headers:{Authorization:'Basic '+Buffer.from('x-token:'+token).toString('base64')},redirect:'error',signal:AbortSignal.timeout(15000)});assert.equal(auth.status,200);const body=await auth.json();registryAuthorization='Bearer '+(body.token??body.access_token);response=await fetch(url,{headers:{Authorization:registryAuthorization,Accept:'application/vnd.oci.image.manifest.v1+json'},redirect:'error',signal:AbortSignal.timeout(15000)});}const bytes=Buffer.from(await response.arrayBuffer());assert(bytes.length<1024*1024);const digest='sha256:'+createHash('sha256').update(bytes).digest('hex');result.registryControls.push({phase,status:response.status,digest,bytes:bytes.length});retain();assert.equal(response.status,200);assert.equal(digest,manifest.imageManifestDigest);}
const workSignal=AbortSignal.timeout(manifest.clientWorkDeadlineMilliseconds);
function boundedClient(signal){const base=createClient({token,orgID:'l4zncjjbj5'});return {...base,rpc:new Proxy(base.rpc,{get(target,key){const method=Reflect.get(target,key);const maximum=key==='createSandbox'?65000:30000;return typeof method==='function'?((input,options)=>Reflect.apply(method,target,[input,{...options,signal:options?.signal?AbortSignal.any([signal,options.signal]):signal,timeoutMs:Math.min(options?.timeoutMs??maximum,maximum)}])):method;}})};}
const client=boundedClient(workSignal);let sandbox;retain();
try{
 await checkTag('before-create');result.createCallCount++;retain();sandbox=await Sandbox.create(client,request);result.created=view(sandbox);retain();
 assert.equal(sandbox.status,'running');assert.equal(sandbox.resources.vcpus,2);assert.equal(sandbox.resources.memoryMb,4096);assert.equal(sandbox.architecture,'amd64');
 result.runtimeReferenceComparison={requested:manifest.imageReference,returned:sandbox.runtime,exactMatch:sandbox.runtime?.imageRef===manifest.imageReference};result.expiryMetadata={lifetimeFromCreationMilliseconds:new Date(sandbox.expiresAt).getTime()-new Date(sandbox.createdAt).getTime(),requestedMinutes:2};retain();
 const program=`import {readFileSync,existsSync,statSync} from 'node:fs';import {createHash} from 'node:crypto';import {execFileSync} from 'node:child_process';const git='/opt/depot-reuse-20261018-r1/git-2.56.0/bin/git';const marker='/opt/depot-reuse-20261018-r1/image-manifest.json';const bytes=readFileSync(git);const value={nonce:process.argv[1],nodeVersion:process.version,architecture:process.arch,git:{path:git,version:execFileSync(git,['--version'],{encoding:'utf8'}).trim(),bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex')},imageManifest:{exists:existsSync(marker),bytes:statSync(marker).size,sha256:createHash('sha256').update(readFileSync(marker)).digest('hex')},syntheticSourcePresent:existsSync('/home/runner/work/Monochromatic/Monochromatic/.reuse-synthetic-source-marker'),syntheticSecretPresent:existsSync('/home/runner/.config/depot/reuse-synthetic-secret')};console.log(JSON.stringify(value));`;
 const command=await sandbox.runCommand({cmd:'node',args:['--input-type=module','-e',program,nonce]});const [stdout,stderr,finished]=await Promise.all([command.stdout(),command.stderr(),command.wait()]);const observed=JSON.parse(stdout);result.checks.push({name:'actual-custom-image-content',commandId:command.cmdId,exitCode:finished.exitCode,stderr,observed});retain();assert.equal(finished.exitCode,0);assert.equal(stderr,'');assert.equal(observed.nonce,nonce);assert.equal(observed.git.version,'git version 2.56.0');assert.equal(observed.git.bytes,20315448);assert.equal(observed.git.sha256,'d42496dde88b0e5bfbdeb8a32f339601635d7007915ce9a9925ba7f7423bc99e');assert(observed.imageManifest.exists);assert.equal(observed.syntheticSourcePresent,false);assert.equal(observed.syntheticSecretPresent,false);
 const remote=sandbox.fs();const artifact='/home/runner/temp/agent/sdk-custom-'+nonce+'.json';const payload=JSON.stringify({nonce,source,unicode:'café 🎵'})+'\n';await remote.writeFile(artifact,payload,{recursive:true,mode:0o600});const downloaded=await remote.readFile(artifact);assert.equal(downloaded.toString(),payload);await remote.unlink(artifact);assert.equal(await remote.exists(artifact),false);result.checks.push({name:'sdk-filesystem-artifact-roundtrip',bytes:downloaded.length,sha256:createHash('sha256').update(downloaded).digest('hex'),removed:true});result.primaryConsumerVerified=true;retain();
 try{const detachedSince=new Date(Date.now()-1000);const detached=await sandbox.runCommand({cmd:'node',args:['-e','console.log(process.argv[1]);console.error(process.argv[2]);','sdk-detached-out-'+nonce,'sdk-detached-err-'+nonce],detached:true});result.detachedCommandId=detached.cmdId;retain();const streamed=[];for await(const entry of sandbox.logs.stream({command:detached,replay:'all',signal:AbortSignal.timeout(5000)})){streamed.push(entry);assert(streamed.length<20);}const fetched=[];for await(const entry of sandbox.logs.fetch({command:detached,since:detachedSince,until:new Date(Date.now()+1000)})){fetched.push(entry);assert(fetched.length<20);}result.detachedLogs={streamed,fetched,streamContainsStdout:streamed.some(row=>row.message==='sdk-detached-out-'+nonce),streamContainsStderr:streamed.some(row=>row.message==='sdk-detached-err-'+nonce),fetchContainsStdout:fetched.some(row=>row.message==='sdk-detached-out-'+nonce),fetchContainsStderr:fetched.some(row=>row.message==='sdk-detached-err-'+nonce)};retain();}catch(error){result.detachedLogError=errorView(error);retain();}
 await checkTag('after-consumer');
}catch(error){result.error=errorView(error);retain();}
finally{
 if(sandbox){const cleanupClient=boundedClient(AbortSignal.timeout(manifest.clientCleanupDeadlineMilliseconds));try{const current=await Sandbox.get(cleanupClient,sandbox.sandboxId);if(!['finished','cancelled','failed'].includes(current.status))await current.stop({blocking:true});const final=await Sandbox.get(cleanupClient,sandbox.sandboxId);result.cleanup.confirmed=view(final);result.cleanup.terminal=['finished','cancelled','failed'].includes(final.status);retain();}catch(error){result.cleanup.error=errorView(error);retain();const rescue=boundedClient(AbortSignal.timeout(30000));try{const current=await Sandbox.get(rescue,sandbox.sandboxId);if(!['finished','cancelled','failed'].includes(current.status))await current.kill();const final=await Sandbox.get(rescue,sandbox.sandboxId);result.cleanup.recovery=view(final);result.cleanup.terminal=['finished','cancelled','failed'].includes(final.status);}catch(error){result.cleanup.recoveryError=errorView(error);}}}else result.cleanup.noIdReturned=true;
 result.finishedAt=new Date().toISOString();retain();console.log(JSON.stringify({source,sandboxId:sandbox?.sandboxId,primaryConsumerVerified:result.primaryConsumerVerified,cleanup:result.cleanup,error:result.error,detachedLogs:result.detachedLogs,detachedLogError:result.detachedLogError}));
}
assert.equal(result.createCallCount,1);assert.equal(result.cleanup.terminal,true);assert.equal(result.primaryConsumerVerified,true);
'''

